import { t, phrase, lesson, choice, option, recall, dialogue } from "./courseAuthoring";
import type { CourseUnit, CoursePhrase, LocaleText } from "./courseTypes";
import type { ItalianDialogueTurn } from "../italianModuleTypes";

type Answer = [string, LocaleText];
function q(id: string, prompt: LocaleText, answers: Answer[], correct: number, explanation: LocaleText, stimulus?: string) {
  return choice(id, prompt, answers.map(([text, feedback], i) => option(`o${i}`, text, feedback)), `o${correct}`, explanation, stimulus ? "listen" : "choice", stimulus);
}
function turn(speaker: string, line: string, prompt: LocaleText, answers: Answer[], correct: number): ItalianDialogueTurn {
  return { speaker, line, prompt, options: answers.map(([text, feedback], i) => option(`o${i}`, text, feedback)), correctId: `o${correct}` };
}

