const u10: CourseUnit = {
  id: "u10", number: 10, title: t("Un séjour qui se passe bien", "A stay that works for you", "Una estancia que funciona"), subtitle: t("Réserver, préciser ses besoins et obtenir de l’aide.", "Book, explain your needs and get help.", "Reservar, expresar necesidades y obtener ayuda."),
  objectives: [t("Donner les détails d’une réservation.", "Give the details of a booking.", "Dar los detalles de una reserva."), t("Décrire un problème concret avec une phrase simple.", "Describe a practical problem in a simple sentence.", "Describir un problema concreto con una frase sencilla."), t("Demander de l’aide et faire clarifier une réponse.", "Ask for help and clarify a reply.", "Pedir ayuda y aclarar una respuesta.")],
  lessons: [
    lesson({ id: "it1-u10-l1", title: t("À la réception", "At reception", "En recepción"), goal: t("Présenter une réservation et vérifier ce qu’elle comprend.", "Introduce a booking and check what it includes.", "Presentar una reserva y comprobar qué incluye."), vocabulary: u10a,
      grammar: { title: t("Pour combien de personnes et de nuits ?", "For how many people and nights?", "¿Para cuántas personas y noches?"), body: t("Pour la durée du séjour, utilise per + nombre + nom : per una notte, per due notti. Notte devient notti au pluriel. A nome introduit le nom de la réservation ; a che ora demande une heure. Vorrei adoucit la demande : retiens cette forme comme une expression utile, sans apprendre ici tout le conditionnel. Inclusa s’accorde avec colazione, féminin ; incluso accompagne un nom masculin : il servizio è incluso. Pose la question sans supposer la réponse.", "For the length of a stay, use per + number + noun: per una notte, per due notti. Notte becomes notti in the plural. A nome introduces the booking name; a che ora asks for a time. Vorrei softens a request: learn it as a useful expression here without learning the whole conditional tense. Inclusa agrees with feminine colazione; incluso goes with a masculine noun, as in il servizio è incluso. Ask without assuming the answer.", "Para la duración de la estancia usa per + número + nombre: per una notte, per due notti. El plural de notte es notti. A nome introduce el nombre de la reserva; a che ora pregunta la hora. Vorrei suaviza la petición: apréndelo como expresión útil, sin estudiar aquí todo el condicional. Inclusa concuerda con colazione, femenino; incluso acompaña a un nombre masculino, como en il servizio è incluso. Pregunta sin dar por hecha la respuesta."), examples: [u10a[0], u10a[1], u10a[3], phrase("Vorrei una camera per tre notti.", "Je voudrais une chambre pour trois nuits.", "I would like a room for three nights.", "Quisiera una habitación para tres noches.")] },
      pronunciation: { body: t("La double consonne de notte est plus longue que la consonne simple de note. Dans prenotazione, l’accent porte sur zio ; dans camera, sur ca. Entraîne la demande en trois groupes : Vorrei / una camera / per due notti.", "The double consonant in notte is longer than the single consonant in note. Prenotazione stresses zio; camera stresses ca. Practise the request in three groups: Vorrei / una camera / per due notti.", "La consonante doble de notte dura más que la simple de note. Prenotazione lleva el acento en zio; camera, en ca. Practica la petición en tres grupos: Vorrei / una camera / per due notti."), practice: ["Una notte. Due notti.", "Una prenotazione a nome Rossi.", "Vorrei una camera per due notti."] },
      reading: phrase("Nella scena del corso, Elena arriva in albergo con Yoppo. Ha una prenotazione a nome Rossi per due notti. Sono due adulti. Elena chiede se la colazione è inclusa: nella loro prenotazione non è inclusa. Prima di lasciare i bagagli, domanda se è possibile. La risposta vale per questa scena.", "Dans la scène du cours, Elena arrive à l’hôtel avec Yoppo. Elle a une réservation au nom de Rossi pour deux nuits. Ils sont deux adultes. Elena demande si le petit-déjeuner est inclus : il ne l’est pas dans leur réservation. Avant de laisser les bagages, elle demande si c’est possible. La réponse vaut pour cette scène.", "In the course scene, Elena arrives at a hotel with Yoppo. She has a reservation under Rossi for two nights. They are two adults. Elena asks if breakfast is included: it is not included in their booking. Before leaving their luggage, she asks whether that is possible. The answer applies to this scene.", "En la escena del curso, Elena llega al hotel con Yoppo. Tiene una reserva a nombre de Rossi para dos noches. Son dos adultos. Elena pregunta si el desayuno está incluido: no lo está en su reserva. Antes de dejar el equipaje, pregunta si es posible. La respuesta corresponde a esta escena."), order: u10a[1], recall: u10a[3],
      comprehension: q("it1-u10-l1-read", t("Qu’est-ce qui n’est pas compris dans cette réservation ?", "What is not included in this booking?", "¿Qué no está incluido en esta reserva?"), [["La camera.", t("Une chambre est bien réservée ; la question porte sur un service supplémentaire.", "A room is booked; the question concerns an additional service.", "Sí hay una habitación reservada; la pregunta trata de un servicio adicional.")], ["La colazione.", t("Le texte précise que le petit-déjeuner n’est pas inclus.", "The text says breakfast is not included.", "El texto indica que el desayuno no está incluido.")], ["La seconda notte.", t("La réservation est bien pour deux nuits.", "The booking is for two nights.", "La reserva es para dos noches.")]], 1, t("Une durée et un service compris sont deux informations différentes.", "The length of a stay and an included service are different details.", "La duración y un servicio incluido son datos distintos.")),
      listening: q("it1-u10-l1-listen", t("Combien de nuits sont demandées ?", "How many nights are requested?", "¿Cuántas noches se piden?"), [["Una notte.", t("Una serait une seule nuit.", "Una would mean one night.", "Una sería una sola noche.")], ["Tre notti.", t("Le nombre entendu est due, pas tre.", "The number heard is due, not tre.", "El número escuchado es due, no tre.")], ["Due notti.", t("Per due notti donne la durée.", "Per due notti gives the duration.", "Per due notti indica la duración.")]], 2, t("Le nombre après per indique la durée de la réservation.", "The number after per gives the booking duration.", "El número después de per indica la duración de la reserva."), "Vorrei una camera per due notti."),
      speaking: { prompt: t("Présente une réservation fictive avec un nom inventé, un nombre de personnes et de nuits. Pose une question sur un service.", "Introduce a fictional reservation with an invented name, number of guests and nights. Ask about a service.", "Presenta una reserva ficticia con un nombre inventado, número de personas y noches. Pregunta por un servicio."), checklist: [t("Je donne le nom de la réservation.", "I give the booking name.", "Doy el nombre de la reserva."), t("Je distingue personnes et nuits.", "I distinguish guests and nights.", "Distingo personas y noches."), t("Je pose une question complète.", "I ask a complete question.", "Hago una pregunta completa.")] },
    }),
    lesson({ id: "it1-u10-l2", title: t("Résoudre un petit problème", "Resolve a practical problem", "Resolver un pequeño problema"), goal: t("Nommer un problème et demander une solution avec courtoisie.", "Name a problem and politely ask for a solution.", "Nombrar un problema y pedir una solución con cortesía."), vocabulary: u10b,
      grammar: { title: t("Ce qui manque et ce qui ne fonctionne pas", "What is missing and what is not working", "Lo que falta y lo que no funciona"), body: t("Non se place avant le verbe : non funziona, non c’è. Non funziona décrit une panne ; non c’è signale une absence. Manca s’accorde avec l’objet qui manque : manca un asciugamano, mancano due asciugamani. Troppo reste ici invariable devant un adjectif, mais l’adjectif s’accorde : la camera è troppo fredda. Dans Può aiutarmi?, mi signifie me et s’attache à l’infinitif : aiutare + mi devient aiutarmi. Apprends la demande entière pour commencer.", "Non goes before the verb: non funziona, non c’è. Non funziona describes something not working; non c’è indicates absence. Manca agrees with the missing item: manca un asciugamano, mancano due asciugamani. Troppo stays unchanged here before an adjective, while the adjective agrees: la camera è troppo fredda. In Può aiutarmi?, mi means me and attaches to the infinitive: aiutare + mi becomes aiutarmi. Start by learning the whole request.", "Non va delante del verbo: non funziona, non c’è. Non funziona describe una avería; non c’è indica una ausencia. Manca concuerda con lo que falta: manca un asciugamano, mancano due asciugamani. Troppo no cambia aquí delante de un adjetivo, pero el adjetivo concuerda: la camera è troppo fredda. En Può aiutarmi?, mi significa me y se une al infinitivo: aiutare + mi da aiutarmi. Empieza aprendiendo la petición completa."), examples: [u10b[0], u10b[1], u10b[3], phrase("Mancano due asciugamani.", "Il manque deux serviettes.", "Two towels are missing.", "Faltan dos toallas.")] },
      pronunciation: { body: t("Dans doccia, garde la consonne longue au milieu. Dans asciugamano, le groupe sc devant i produit le son de ch en français. Ralentis avant le mot qui décrit le problème : non funziona / la doccia.", "In doccia, keep the long consonant in the middle. In asciugamano, sc before i has the sh sound. Slow down before the word naming the problem: non funziona / la doccia.", "En doccia, mantén larga la consonante central. En asciugamano, sc delante de i representa el sonido sh. Haz una pequeña pausa antes de lo que causa el problema: non funziona / la doccia."), practice: ["Doccia. Non funziona la doccia.", "Un asciugamano. Due asciugamani.", "Può aiutarmi, per favore?"] },
      reading: phrase("Yoppo entra nella camera e controlla le sue cose. C’è un asciugamano, ma sono due persone: manca un asciugamano. Poi prova la doccia. La doccia funziona, ma non c’è acqua calda. Alla reception dice: «Non c’è acqua calda. Può aiutarmi, per favore?». Descrive il problema prima di chiedere una soluzione.", "Yoppo entre dans la chambre et vérifie ses affaires. Il y a une serviette, mais ils sont deux : il manque une serviette. Puis il essaie la douche. La douche fonctionne, mais il n’y a pas d’eau chaude. À la réception, il dit : « Il n’y a pas d’eau chaude. Pouvez-vous m’aider, s’il vous plaît ? ». Il décrit le problème avant de demander une solution.", "Yoppo enters the room and checks his things. There is one towel, but there are two people: one towel is missing. Then he tries the shower. The shower works, but there is no hot water. At reception he says, “There is no hot water. Can you help me, please?” He describes the problem before asking for a solution.", "Yoppo entra en la habitación y revisa sus cosas. Hay una toalla, pero son dos personas: falta una toalla. Luego prueba la ducha. La ducha funciona, pero no hay agua caliente. En recepción dice: «No hay agua caliente. ¿Puede ayudarme, por favor?». Describe el problema antes de pedir una solución."), order: u10b[4], recall: u10b[1],
      comprehension: q("it1-u10-l2-read", t("Quel problème Yoppo signale-t-il à la réception ?", "Which problem does Yoppo report at reception?", "¿Qué problema comunica Yoppo en recepción?"), [["Non c’è acqua calda.", t("C’est la phrase qu’il utilise à la réception.", "That is the sentence he uses at reception.", "Es la frase que usa en recepción.")], ["Non c’è una camera.", t("Il est déjà entré dans sa chambre.", "He has already entered his room.", "Ya ha entrado en su habitación.")], ["La camera è troppo calda.", t("Le texte ne décrit pas la température de la chambre.", "The text does not describe the room temperature.", "El texto no describe la temperatura de la habitación.")]], 0, t("L’eau chaude, la chambre et sa température ne sont pas interchangeables.", "Hot water, the room and its temperature are separate details.", "El agua caliente, la habitación y su temperatura son datos distintos.")),
      listening: q("it1-u10-l2-listen", t("Qu’est-ce qui manque ?", "What is missing?", "¿Qué falta?"), [["Una prenotazione.", t("Prenotazione désigne une réservation, pas l’objet entendu.", "Prenotazione means a booking, not the item heard.", "Prenotazione es una reserva, no el objeto escuchado.")], ["Un asciugamano.", t("Asciugamano désigne la serviette.", "Asciugamano means towel.", "Asciugamano significa toalla.")], ["Una chiave.", t("Chiave désigne une clé ; ce n’est pas le mot entendu.", "Chiave means key; that is not the word heard.", "Chiave significa llave; no es la palabra escuchada.")]], 1, t("Manca est suivi de l’objet manquant.", "Manca is followed by the missing item.", "Después de manca aparece el objeto que falta."), "Manca un asciugamano."),
      speaking: { prompt: t("Choisis deux problèmes fictifs dans la chambre. Explique-les à Yoppo, puis demande de l’aide ou un changement.", "Choose two imaginary room problems. Explain them to Yoppo, then ask for help or a change.", "Elige dos problemas ficticios de la habitación. Explícalos a Yoppo y pide ayuda o un cambio."), checklist: [t("Je nomme précisément ce qui manque ou ne fonctionne pas.", "I name exactly what is missing or not working.", "Nombro con precisión lo que falta o no funciona."), t("Je place non devant le verbe quand il le faut.", "I put non before the verb when needed.", "Coloco non delante del verbo cuando hace falta."), t("Je termine par une demande polie.", "I finish with a polite request.", "Termino con una petición cortés.")] },
    }),
    lesson({ id: "it1-u10-l3", title: t("Obtenir une aide compréhensible", "Get help you can understand", "Obtener ayuda que se entiende"), goal: t("Exprimer un besoin et faire répéter ou écrire une information.", "Express a need and ask for information to be repeated or written down.", "Expresar una necesidad y pedir que repitan o escriban la información."), vocabulary: u10c,
      grammar: { title: t("Può…? et ho bisogno di…", "Può…? and ho bisogno di…", "Può…? y ho bisogno di…"), body: t("Pour une personne à qui l’on s’adresse avec Lei, utilise Può + infinitif : Può ripetere?, Può scrivere? Le sujet Lei peut rester sous-entendu. Ho bisogno di introduit un nom ou un infinitif : di aiuto, di riposare. Cerco signifie je cherche et prend directement son complément : cerco una farmacia. Non mi sento bene est une expression à mémoriser pour signaler un malaise ; cette leçon entraîne la demande d’assistance, pas un diagnostic.", "When addressing one person with polite Lei, use Può + infinitive: Può ripetere?, Può scrivere? Lei can remain unstated. Ho bisogno di takes a noun or infinitive: di aiuto, di riposare. Cerco means I am looking for and takes its object directly: cerco una farmacia. Learn Non mi sento bene as a phrase to say you feel unwell; this lesson practises asking for assistance, not making a diagnosis.", "Al dirigirte a una persona con Lei de cortesía, usa Può + infinitivo: Può ripetere?, Può scrivere? El sujeto Lei puede omitirse. Ho bisogno di introduce un nombre o infinitivo: di aiuto, di riposare. Cerco significa busco y lleva directamente su complemento: cerco una farmacia. Aprende Non mi sento bene como expresión para comunicar malestar; esta lección practica pedir ayuda, no hacer un diagnóstico."), examples: [u10c[0], u10c[3], u10c[6], phrase("Ho bisogno di riposare.", "J’ai besoin de me reposer.", "I need to rest.", "Necesito descansar.")] },
      pronunciation: { body: t("Può est une syllabe accentuée ; garde ensuite le rythme du groupe Può ripetere. Dans indirizzo, la double z est nette. Dis plus lentement la demande elle-même : Può parlare / più lentamente? Tu peux faire une pause sans interrompre le sens.", "Può is one stressed syllable; then keep the rhythm of Può ripetere. The double z in indirizzo is clear. Say the request itself slowly: Può parlare / più lentamente? You can pause without breaking the meaning.", "Può es una sílaba acentuada; mantén después el ritmo del grupo Può ripetere. La doble z de indirizzo se oye con claridad. Di despacio la propia petición: Può parlare / più lentamente? Puedes hacer una pausa sin romper el sentido."), practice: ["Può ripetere, per favore?", "Può scrivere l’indirizzo?", "Ho bisogno di aiuto."] },
      reading: phrase("Sara cerca una farmacia. Alla reception chiede un indirizzo, ma la risposta è troppo veloce. Non dice subito «Ho capito». Dice: «Può parlare più lentamente?». Poi domanda: «Può scrivere l’indirizzo?». Ora può leggere il nome della strada e controllare il numero con Yoppo.", "Sara cherche une pharmacie. À la réception, elle demande une adresse, mais la réponse est trop rapide. Elle ne dit pas tout de suite « J’ai compris ». Elle dit : « Pouvez-vous parler plus lentement ? ». Puis elle demande : « Pouvez-vous écrire l’adresse ? ». Maintenant elle peut lire le nom de la rue et vérifier le numéro avec Yoppo.", "Sara is looking for a pharmacy. At reception she asks for an address, but the reply is too fast. She does not immediately say “I understood.” She says, “Can you speak more slowly?” Then she asks, “Can you write down the address?” Now she can read the street name and check the number with Yoppo.", "Sara busca una farmacia. En recepción pide una dirección, pero la respuesta es demasiado rápida. No dice enseguida «He entendido». Dice: «¿Puede hablar más despacio?». Después pregunta: «¿Puede escribir la dirección?». Ahora puede leer el nombre de la calle y comprobar el número con Yoppo."), order: u10c[4], recall: u10c[0],
      comprehension: q("it1-u10-l3-read", t("Pourquoi Sara demande-t-elle d’écrire l’adresse ?", "Why does Sara ask for the address in writing?", "¿Por qué Sara pide que escriban la dirección?"), [["Per prenotare una camera.", t("Elle cherche une pharmacie, pas une nouvelle réservation.", "She is looking for a pharmacy, not a new booking.", "Busca una farmacia, no una nueva reserva.")], ["Per cambiare il nome della strada.", t("Elle veut comprendre le nom, pas le changer.", "She wants to understand the name, not change it.", "Quiere entender el nombre, no cambiarlo.")], ["Per leggere e controllare l’informazione.", t("L’écrit lui permet de vérifier le nom et le numéro.", "Writing lets her check the name and number.", "Por escrito puede comprobar el nombre y el número.")]], 2, t("Faire préciser une réponse est une stratégie de communication.", "Asking for clarification is a communication strategy.", "Pedir una aclaración es una estrategia de comunicación.")),
      listening: q("it1-u10-l3-listen", t("Quelle adaptation est demandée ?", "What change is being requested?", "¿Qué cambio se pide?"), [["Parlare più lentamente.", t("La demande porte sur la vitesse de parole.", "The request concerns speaking speed.", "La petición trata de la velocidad al hablar.")], ["Scrivere il prezzo.", t("Ni écrire ni prix n’apparaissent dans l’audio.", "Neither writing nor price appears in the audio.", "No se mencionan ni escribir ni el precio.")], ["Cambiare camera.", t("Cette demande concernerait une chambre, pas la compréhension.", "That would concern a room, not understanding.", "Esa petición trataría de una habitación, no de comprender.")]], 0, t("Più lentamente signifie plus lentement.", "Più lentamente means more slowly.", "Più lentamente significa más despacio."), "Può parlare più lentamente, per favore?"),
      speaking: { prompt: t("Joue une demande d’aide à la réception. Choisis un besoin, demande de répéter puis demande une information écrite.", "Roleplay asking for help at reception. Choose a need, ask for a repeat, then ask for information in writing.", "Interpreta una petición de ayuda en recepción. Elige una necesidad, pide que repitan y después pide información por escrito."), checklist: [t("J’exprime un besoin identifiable.", "I express an identifiable need.", "Expreso una necesidad identificable."), t("J’utilise Può + infinitif.", "I use Può + infinitive.", "Uso Può + infinitivo."), t("Je vérifie ce que je comprends.", "I check what I understand.", "Compruebo lo que entiendo.")] },
      extra: [dialogue("it1-u10-reception-dialogue", t("Yoppo à la réception", "Yoppo at reception", "Yoppo en recepción"), t("Présente la réservation Rossi, signale l’absence d’eau chaude puis demande de répéter la réponse.", "Introduce the Rossi booking, report that there is no hot water, then ask for the reply again.", "Presenta la reserva Rossi, comunica que no hay agua caliente y pide que repitan la respuesta."), [
        turn("Receptionist", "Buonasera. Ha una prenotazione?", t("Donne le nom de la réservation.", "Give the booking name.", "Da el nombre de la reserva."), [["Ho una prenotazione a nome Rossi.", t("Tu réponds à la question avec le nom utile.", "You answer with the relevant name.", "Respondes con el nombre necesario.")], ["Manca un asciugamano.", t("C’est un problème à signaler plus tard, pas le nom demandé.", "That is a later problem, not the requested name.", "Es un problema posterior, no el nombre solicitado.")], ["Sono le nove.", t("L’heure ne permet pas d’identifier la réservation.", "The time does not identify the booking.", "La hora no identifica la reserva.")]], 0),
        turn("Receptionist", "Ecco la camera. C’è un problema?", t("Explique que l’eau n’est pas chaude.", "Explain that there is no hot water.", "Explica que no hay agua caliente."), [["La colazione è inclusa?", t("Tu demandes un service au lieu de signaler l’eau.", "You ask about a service instead of the water.", "Preguntas por un servicio en lugar de comunicar lo del agua.")], ["Non c’è acqua calda.", t("Tu identifies précisément le problème.", "You identify the exact problem.", "Identificas el problema con precisión.")], ["Vorrei un biglietto.", t("Un billet n’aide pas à décrire ce problème de chambre.", "A ticket does not describe this room problem.", "Un billete no describe este problema de habitación.")]], 1),
        turn("Receptionist", "Certo, posso aiutarla. La nuova camera è al primo piano.", t("La réponse est trop rapide : demande de répéter sans prétendre avoir compris.", "The reply is too fast: ask for a repeat without pretending you understood.", "La respuesta es demasiado rápida: pide que repitan sin fingir que has entendido."), [["Ho capito tutto, grazie.", t("Cette réponse affirme une compréhension que la consigne exclut.", "That claims understanding the task says you do not have.", "Eso afirma una comprensión que la consigna excluye.")], ["Non ho una prenotazione.", t("Cela contredit le début de l’échange.", "That contradicts the start of the exchange.", "Eso contradice el comienzo del intercambio.")], ["Può ripetere, per favore?", t("Tu demandes la précision nécessaire avec courtoisie.", "You politely ask for the clarification you need.", "Pides con cortesía la aclaración necesaria.")]], 2),
      ], t("Une interaction réussie peut inclure une demande de répétition : il faut comprendre la solution.", "A successful interaction can include asking for a repeat: you need to understand the solution.", "Una interacción lograda puede incluir pedir que repitan: necesitas entender la solución."))],
    }),
  ],
  quiz: { id: "it1-u10-quiz", title: t("Bilan : demander un service", "Check-in: ask for a service", "Repaso: pedir un servicio"), description: t("Cinq situations de séjour et d’assistance.", "Five accommodation and assistance situations.", "Cinco situaciones de alojamiento y ayuda."), unitIds: ["u10"], passPercent: 80, questions: [
    q("it1-u10-quiz-q1", t("Tu veux connaître l’heure d’arrivée possible. Quelle question poses-tu ?", "You want to know the possible arrival time. What do you ask?", "Quieres saber la hora posible de llegada. ¿Qué preguntas?"), [["Quante notti?", t("Cette question porte sur la durée.", "That asks about duration.", "Eso pregunta la duración.")], ["A che ora possiamo arrivare?", t("A che ora demande précisément une heure.", "A che ora asks specifically for a time.", "A che ora pregunta precisamente una hora.")], ["La colazione è inclusa?", t("Cette question porte sur un service compris.", "That asks about an included service.", "Eso pregunta por un servicio incluido.")]], 1, t("Choisis une question adaptée à l’information manquante.", "Choose the question for the missing information.", "Elige la pregunta correspondiente al dato que falta.")),
    q("it1-u10-quiz-q2", t("Quel est le besoin entendu ?", "What need do you hear?", "¿Qué necesidad escuchas?"), [["Cambiare il biglietto.", t("Le billet n’est pas mentionné.", "A ticket is not mentioned.", "No se menciona un billete.")], ["Lasciare i bagagli.", t("Aucun bagage n’est mentionné.", "No luggage is mentioned.", "No se menciona equipaje.")], ["Riposare.", t("La personne dit avoir besoin de repos.", "The speaker says they need to rest.", "La persona dice que necesita descansar.")]], 2, t("Ho bisogno di peut précéder l’infinitif riposare.", "Ho bisogno di can come before the infinitive riposare.", "Ho bisogno di puede ir delante del infinitivo riposare."), "Ho bisogno di riposare."),
    recall("it1-u10-quiz-q3", phrase("Vorrei una camera per tre notti.", "Je voudrais une chambre pour trois nuits.", "I would like a room for three nights.", "Quisiera una habitación para tres noches.")),
    q("it1-u10-quiz-q4", t("Deux serviettes manquent. Complète : … due asciugamani.", "Two towels are missing. Complete: … due asciugamani.", "Faltan dos toallas. Completa: … due asciugamani."), [["Mancano", t("Le sujet due asciugamani est pluriel.", "The subject due asciugamani is plural.", "El sujeto due asciugamani es plural.")], ["Manca", t("Manca conviendrait avec un seul objet.", "Manca would fit one item.", "Manca correspondería a un solo objeto.")], ["Manco", t("Manco correspond à io, pas à deux serviettes.", "Manco goes with io, not two towels.", "Manco corresponde a io, no a dos toallas.")]], 0, t("Le verbe s’accorde avec ce qui manque.", "The verb agrees with what is missing.", "El verbo concuerda con lo que falta.")),
    q("it1-u10-quiz-q5", t("Tu comprends mal une adresse dite à voix haute. Quelle demande permet de la lire ?", "You cannot clearly understand a spoken address. What request lets you read it?", "No entiendes bien una dirección oral. ¿Qué petición permite leerla?"), [["Può cambiare l’indirizzo?", t("Tu veux lire l’adresse, pas la changer.", "You want to read the address, not change it.", "Quieres leer la dirección, no cambiarla.")], ["Può scrivere l’indirizzo?", t("Scrivere demande la forme écrite.", "Scrivere asks for the written form.", "Scrivere pide la forma escrita.")], ["A che ora arriva?", t("Cette question porte sur une heure d’arrivée.", "That asks for an arrival time.", "Eso pregunta una hora de llegada.")]], 1, t("Demander une autre forme de l’information peut aider à la comprendre.", "Asking for information in another form can help understanding.", "Pedir la información de otra forma puede ayudar a comprenderla.")),
  ] },
  production: { id: "it1-u10-project", title: t("Ton séjour, tes besoins", "Your stay, your needs", "Tu estancia, tus necesidades"), prompt: t("Imagine un séjour qui te convient : choisis un nom fictif, les personnes, la durée et un service à vérifier. Rédige un dialogue de six répliques : réservation, question, réponse imaginée, problème concret, demande d’aide et demande de clarification. Adapte les détails au lieu de recopier le modèle.", "Imagine a stay that suits you: choose a fictional name, guests, duration and a service to check. Write a six-line dialogue: booking, question, imagined reply, practical problem, request for help and request for clarification. Adapt the details instead of copying the model.", "Imagina una estancia adecuada para ti: elige nombre ficticio, personas, duración y un servicio que comprobar. Escribe seis intervenciones: reserva, pregunta, respuesta imaginada, problema concreto, petición de ayuda y aclaración. Adapta los detalles en lugar de copiar el modelo."), model: "Ho una prenotazione a nome Costa: siamo due adulti, per tre notti. La colazione è inclusa? Sì, in questa prenotazione è inclusa. Nella camera manca un asciugamano. Può aiutarmi, per favore? Può ripetere più lentamente?", rubric: [t("Les détails de ma réservation sont cohérents.", "My booking details are consistent.", "Los datos de mi reserva son coherentes."), t("Je pose une question sur un service.", "I ask about a service.", "Pregunto por un servicio."), t("Mon problème est précis et ma demande polie.", "My problem is specific and my request polite.", "Mi problema es concreto y mi petición cortés."), t("Je fais clarifier une réponse.", "I ask for a reply to be clarified.", "Pido una aclaración de una respuesta.")] },
  culture: { title: t("Les besoins se demandent", "Ask about individual needs", "Preguntar por las necesidades"), body: t("Dans nos scènes, les besoins et les services changent d’une réservation à l’autre. Demander si quelque chose est inclus, accessible ou possible évite de supposer que toutes les personnes et tous les hébergements fonctionnent de la même manière. Tu peux utiliser un nom fictif pour la pratique et choisir les détails personnels que tu souhaites communiquer. Compare ensuite cette façon de demander un service avec une langue que tu connais.", "In our scenes, needs and services vary between bookings. Asking whether something is included, accessible or possible avoids assuming that all people and accommodation work the same way. Use a fictional name for practice and choose which personal details you want to share. Then compare these service requests with a language you know.", "En nuestras escenas, las necesidades y los servicios cambian según la reserva. Preguntar si algo está incluido, es accesible o es posible evita suponer que todas las personas y alojamientos funcionan igual. Puedes usar un nombre ficticio y elegir qué detalles personales compartir. Compara después estas peticiones de servicio con una lengua que conozcas."), sourceIds: ["cefr"] },
};

